-- LAN-560 발음 평가 자산의 단어 음성 URL을 (억양, 단어) 공용 주소로 옮긴다.
--
-- 옛 주소: .../content/expression-pronunciation-audio/{표현id}/{억양}/word/{순서}/{해시}.mp3
-- 새 주소: .../content/expression-pronunciation-audio/word/{억양}/{해시}.mp3
--
-- 파일 이름의 해시는 (모델·보이스·텍스트·포맷)으로만 계산되므로 같은 (억양, 단어)는 이미 같은
-- 해시를 갖는다. 그래서 경로 앞부분만 바꾸면 되고 새 음성을 만들지 않는다. 문장·표현 음성은
-- 표현마다 텍스트가 달라 중복이 거의 없으므로 지금 경로를 그대로 둔다.
--
-- 근거 (S3 landit-content-982529430654):
--   공용 풀 색인   : content/expression-pronunciation-audio/word-pool/728b9ec0f0a97324c88bf82c3d262f3ee667a8a88ef340d72f399549ebb40fa7.json
--   허용 목록      : 그 색인의 published 항목 10494개, sha256 9b3f654c1d8f9302076180decd5fa7b9a0db51f1096627b5079240b9951930fd
--
-- 트랜잭션은 Flyway가 관리하므로 BEGIN/COMMIT을 두지 않는다.
-- psql로 직접 실행할 때는 -1(single-transaction)로 감쌀 것.

SELECT pg_advisory_xact_lock(hashtext('lan560-shared-word-audio-urls'));
LOCK TABLE expression_pronunciation_asset IN SHARE ROW EXCLUSIVE MODE;

-- 공용 자리에 실물이 있다고 확인된 (억양, 해시)만 담는다.
CREATE TEMP TABLE lan560_shared_word_audio (
    accent_locale TEXT NOT NULL,
    fingerprint TEXT NOT NULL,
    PRIMARY KEY (accent_locale, fingerprint)
) ON COMMIT DROP;


-- 변경 범위를 사후에 증명하기 위한 원본 스냅샷.
CREATE TEMP TABLE lan560_original_assets ON COMMIT DROP AS
SELECT id, words, expression_audio_url, sentence_audio_url
FROM expression_pronunciation_asset;

-- 단어 URL을 구성 요소로 쪼갠 적재 전 스냅샷.
CREATE TEMP TABLE lan560_word_urls ON COMMIT DROP AS
SELECT asset.id,
       asset.accent_locale::TEXT AS row_locale,
       element.ordinality,
       element.value ->> 'audioUrl' AS url,
       parsed.matched[2] AS url_locale,
       parsed.matched[4] AS fingerprint
FROM expression_pronunciation_asset asset
CROSS JOIN LATERAL jsonb_array_elements(asset.words)
    WITH ORDINALITY AS element(value, ordinality)
CROSS JOIN LATERAL (
    SELECT regexp_match(element.value ->> 'audioUrl', '^.*/content/expression-pronunciation-audio/([0-9]+)/(EN_US|EN_GB|EN_AU)/word/([0-9]+)/([0-9a-f]{64})\.mp3$') AS matched
) AS parsed;

DO $$
DECLARE
    bad_rows integer;
    missing_key integer;
    bad_format integer;
    locale_mismatch integer;
    already_shared integer;
    missing RECORD;
BEGIN
    SELECT count(*) INTO bad_rows
    FROM expression_pronunciation_asset
    WHERE jsonb_typeof(words) <> 'array' OR jsonb_array_length(words) = 0;
    IF bad_rows <> 0 THEN
        RAISE EXCEPTION 'LAN-560 words precondition failed: % rows are not a non-empty array', bad_rows;
    END IF;

    SELECT count(*) INTO missing_key
    FROM expression_pronunciation_asset asset
    CROSS JOIN LATERAL jsonb_array_elements(asset.words) AS element(value)
    WHERE NOT (element.value ? 'audioUrl') OR element.value ->> 'audioUrl' IS NULL;
    IF missing_key <> 0 THEN
        RAISE EXCEPTION 'LAN-560 words precondition failed: % elements have no audioUrl', missing_key;
    END IF;

    SELECT count(*) INTO already_shared
    FROM lan560_word_urls WHERE url ~ '^.*/content/expression-pronunciation-audio/word/(EN_US|EN_GB|EN_AU)/[0-9a-f]{64}\.mp3$';
    IF already_shared <> 0 THEN
        RAISE EXCEPTION 'LAN-560 word audio precondition failed: % URLs already use the shared path', already_shared;
    END IF;

    SELECT count(*) INTO bad_format FROM lan560_word_urls WHERE fingerprint IS NULL;
    IF bad_format <> 0 THEN
        RAISE EXCEPTION 'LAN-560 word audio precondition failed: % URLs are not in the expected old format', bad_format;
    END IF;

    SELECT count(*) INTO locale_mismatch
    FROM lan560_word_urls WHERE url_locale IS DISTINCT FROM row_locale;
    IF locale_mismatch <> 0 THEN
        RAISE EXCEPTION 'LAN-560 word audio precondition failed: % URLs disagree with their row accent locale', locale_mismatch;
    END IF;

    SELECT source.url_locale, source.fingerprint INTO missing
    FROM lan560_word_urls source
    LEFT JOIN lan560_shared_word_audio pool
      ON pool.accent_locale = source.url_locale
     AND pool.fingerprint = source.fingerprint
    WHERE pool.accent_locale IS NULL
    ORDER BY source.url_locale, source.fingerprint
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'LAN-560 word audio precondition failed: shared object is missing for % %',
            missing.url_locale, missing.fingerprint;
    END IF;
END $$;

WITH patched AS (
    SELECT original.id,
           jsonb_agg(
               jsonb_set(
                   element.value,
                   ARRAY['audioUrl'],
                   to_jsonb(regexp_replace(element.value ->> 'audioUrl',
                       '^(.*/content/expression-pronunciation-audio/)[0-9]+/(EN_US|EN_GB|EN_AU)/word/[0-9]+/([0-9a-f]{64}\.mp3)$',
                       '\1word/\2/\3')),
                   false
               )
               ORDER BY element.ordinality
           ) AS words
    FROM lan560_original_assets original
    CROSS JOIN LATERAL jsonb_array_elements(original.words)
        WITH ORDINALITY AS element(value, ordinality)
    GROUP BY original.id
)
UPDATE expression_pronunciation_asset asset
SET words = patched.words,
    updated_at = CURRENT_TIMESTAMP
FROM patched
WHERE asset.id = patched.id;

DO $$
DECLARE
    still_old integer;
    not_shared integer;
    changed_other integer;
    changed_fingerprint integer;
    changed_audio_urls integer;
BEGIN
    SELECT count(*) INTO still_old
    FROM expression_pronunciation_asset asset
    CROSS JOIN LATERAL jsonb_array_elements(asset.words) AS element(value)
    WHERE element.value ->> 'audioUrl' ~ '^.*/content/expression-pronunciation-audio/([0-9]+)/(EN_US|EN_GB|EN_AU)/word/([0-9]+)/([0-9a-f]{64})\.mp3$';
    IF still_old <> 0 THEN
        RAISE EXCEPTION 'LAN-560 word audio postcondition failed: % URLs still use the old path', still_old;
    END IF;

    SELECT count(*) INTO not_shared
    FROM expression_pronunciation_asset asset
    CROSS JOIN LATERAL jsonb_array_elements(asset.words) AS element(value)
    WHERE element.value ->> 'audioUrl' !~ '^.*/content/expression-pronunciation-audio/word/(EN_US|EN_GB|EN_AU)/[0-9a-f]{64}\.mp3$';
    IF not_shared <> 0 THEN
        RAISE EXCEPTION 'LAN-560 word audio postcondition failed: % URLs are not in the shared format', not_shared;
    END IF;

    -- audioUrl만 빼고 비교한다. 배열 길이·순서와 나머지 필드가 전부 그대로여야 한다.
    SELECT count(*) INTO changed_other
    FROM lan560_original_assets original
    JOIN expression_pronunciation_asset asset ON asset.id = original.id
    WHERE (SELECT jsonb_agg(e.value - 'audioUrl' ORDER BY e.ordinality)
           FROM jsonb_array_elements(original.words) WITH ORDINALITY AS e(value, ordinality))
      IS DISTINCT FROM
          (SELECT jsonb_agg(e.value - 'audioUrl' ORDER BY e.ordinality)
           FROM jsonb_array_elements(asset.words) WITH ORDINALITY AS e(value, ordinality));
    IF changed_other <> 0 THEN
        RAISE EXCEPTION 'LAN-560 word audio postcondition failed: % rows changed a field other than audioUrl', changed_other;
    END IF;

    -- 해시는 그대로여야 한다. 경로만 바뀌고 다른 단어의 음성으로 바꿔치기되지 않았음을 증명한다.
    SELECT count(*) INTO changed_fingerprint
    FROM lan560_original_assets original
    JOIN expression_pronunciation_asset asset ON asset.id = original.id
    WHERE (SELECT jsonb_agg(substring(e.value ->> 'audioUrl' from '([0-9a-f]{64})\.mp3$') ORDER BY e.ordinality)
           FROM jsonb_array_elements(original.words) WITH ORDINALITY AS e(value, ordinality))
      IS DISTINCT FROM
          (SELECT jsonb_agg(substring(e.value ->> 'audioUrl' from '([0-9a-f]{64})\.mp3$') ORDER BY e.ordinality)
           FROM jsonb_array_elements(asset.words) WITH ORDINALITY AS e(value, ordinality));
    IF changed_fingerprint <> 0 THEN
        RAISE EXCEPTION 'LAN-560 word audio postcondition failed: % rows changed a word fingerprint', changed_fingerprint;
    END IF;

    SELECT count(*) INTO changed_audio_urls
    FROM lan560_original_assets original
    JOIN expression_pronunciation_asset asset ON asset.id = original.id
    WHERE asset.expression_audio_url IS DISTINCT FROM original.expression_audio_url
       OR asset.sentence_audio_url IS DISTINCT FROM original.sentence_audio_url;
    IF changed_audio_urls <> 0 THEN
        RAISE EXCEPTION 'LAN-560 word audio postcondition failed: % rows changed sentence or expression audio URL', changed_audio_urls;
    END IF;
END $$;
